    enemy_territory = items_list(observation.get("opponent_territory"))
    hazards = items_list(observation.get("hazards")) or items_list(observation.get("walls"))

    # Build a small candidate set and pick by heuristic; robust across tasks.
    candidates = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]

    def in_bounds(p):
