            if hp is None:
                continue
            d = manhattan(p, hp)
            if d == 0:
                s -= 6
            elif d == 1:
                s -= 2
        return s

    def opp_pressure_score(p):
        d = manhattan(p, opp_pos)
        if env == "pursuit_evasion" and role == "pursuer":
            return -d
        if env == "pursuit_evasion":
            return d
        return -max(0, 2 - d)

    best_move = [0, 0]
    best_score = None

    for mv in candidates:
        np = [self_pos[0] + mv[0], self_pos[1] + mv[1]]
        if not in_bounds(np):
            continue

        score = 0
        if env == "pursuit_evasion":
            if role == "pursuer":
                score += -manhattan(np, opp_pos) * 4
            else:
                corners = []
