                        d = manhattan(np, c)
                        if d > far:
                            far = d
                    score += far * 2
                score += manhattan(np, opp_pos)
        elif env == "territory_control":
            score += nearest_target_score(np, unclaimed) * 3
            score += nearest_target_score(np, enemy_territory) * 2
            score += opp_pressure_score(np)
        else:
            score += nearest_target_score(np, resources) * 4
            score += opp_pressure_score(np)
